<template><admin-layout><Head :title="$t(&quot;UMI 业务管理 · Deepro&quot;)"/><main class="ub-page">
<div class="ub-heading"><div><span class="ub-eyebrow">UMI / OPERATIONS</span><h1>{{ $t("UMI 业务管理") }}</h1><p>{{ $t("历史接续、计划、每日结算与交易所资金划转。") }}</p></div><div><a :href="route('admin.umi.continuity')">{{ $t("历史权益接续 →") }}</a> · <a :href="route('admin.umi')">{{ $t("原用户档案 ↗") }}</a></div></div>
<div class="ub-notice"><strong>{{state.funded_live?$t("UMI 收益业务"):state.read_only?$t("云端核验"):$t("本地验收")}}</strong><span>{{ $t("业务日期") }} {{state.date}} {{ $t("· 原始资料保留，已接续权益参与收益计算。") }}</span><b>{{state.read_only?$t("只读核验"):state.paused?$t("业务已暂停"):$t("业务运行中")}}</b></div>
<div v-if="state.read_only" class="ub-notice"><strong>{{ $t("资金接续待验收") }}</strong><span>{{ $t("完整业务页面已发布；原用户资料与关系可核查。UMI 真实入金及历史权益接续尚未完成，因此认购、收益发放、兑换和解押暂不执行。") }}</span></div>
<div class="ub-admin-summary"><article class="ub-card"><span>{{ $t("业务账户") }}</span><h2>{{accountTotal}}</h2></article><article class="ub-card"><span>{{ $t("账本核查") }}</span><h2 :class="audit.ok?'ub-ok':'ub-bad'">{{audit.ok?$t("平衡"):$t("需核查")}}</h2><small>{{audit.entries}} {{ $t("条分录") }}</small></article><article class="ub-card"><span>{{ $t("规则版本") }}</span><h2>#{{state.rule_id || $t("待初始化")}}</h2></article><article class="ub-card"><span>{{ $t("下一结算日期") }}</span><h2>{{state.next_date}}</h2></article></div>
<p v-if="!audit.ok" class="ub-error">{{audit.errors.join('；')}}</p><p v-if="message" class="ub-feedback" role="status">{{message}}</p><p v-if="error" class="ub-error" role="alert">{{error}}</p>
<section v-if="state.funded_live" class="ub-card"><h2>{{ $t("收益与兑换资金池") }}</h2><p>{{ $t("从当前管理员自己的 BSC 资金账户转入。收益使用已登记的 UMI 发行余额；USDT 兑换使用实际转入库存。") }}</p><form @submit.prevent="submit({action:'fund_pool',pool:poolTarget,asset:poolAsset,amount:poolAmount})"><fieldset :disabled="busy" class="ub-fieldset"><label>{{ $t("用途") }}<themed-select v-model="poolTarget"><option value="distribution">{{ $t("收益发放") }}</option><option value="inventory">{{ $t("兑换库存") }}</option></themed-select></label><label>{{ $t("资产") }}<themed-select v-model="poolAsset"><option>UMI</option><option>USDT</option></themed-select></label><label>{{ $t("数量") }}<input v-model.trim="poolAmount" required inputmode="decimal" /></label><button class="ub-primary">{{ $t("转入资金池") }}</button></fieldset></form><dl><div v-for="p in pools" :key="p.bucket+p.asset"><dt>{{p.bucket==='system:distribution'?$t("收益池"):$t("兑换池")}} · {{p.asset}}</dt><dd>{{fmt(p.amount)}}</dd></div></dl><p v-if="settlementError" class="ub-error">{{settlementError}}</p></section><nav class="ub-tabs" :aria-label="$t(&quot;UMI 管理导航&quot;)"><button v-for="t in tabs" :key="t.id" :class="{selected:tab===t.id}" @click="tab=t.id">{{t.name}}</button></nav>
<template v-if="tab==='accounts'">
<section class="ub-card"><h2>{{ $t("业务账户") }}</h2><form class="ub-filter" @submit.prevent="$inertia.get(route('admin.umi.business'),{search,...accountForm,account:portfolio?.account.id})"><label>{{ $t('Search') }}<input v-model="search" :placeholder="$t('编号') + ' / ' + $t('邀请编号')" maxlength="100"></label><label>{{ $t('Level') }}<themed-select v-model="accountForm.level"><option value="">{{ $t('All') }}</option><option v-for="n in 10" :value="n-1" :key="n">V{{n-1}}</option></themed-select></label><label>{{ $t('Account binding') }}<themed-select v-model="accountForm.binding"><option value="">{{ $t('All') }}</option><option value="bound">{{ $t('Bound') }}</option><option value="unbound">{{ $t('Unbound') }}</option></themed-select></label><label>{{ $t('Reward eligibility') }}<themed-select v-model="accountForm.rewards"><option value="">{{ $t('All') }}</option><option value="included">{{ $t('Included') }}</option><option value="excluded">{{ $t('Excluded') }}</option></themed-select></label><button>{{ $t('Search') }}</button><Link :href="route('admin.umi.business')">{{ $t('Reset') }}</Link></form><p>{{ $t("原用户按原关系接续；未绑定的账户保留位置和收益，身份核定后才能领取。") }}</p><div class="ub-table"><table><thead><tr><th>{{ $t("编号") }}</th><th>{{ $t("邀请编号 / 上级") }}</th><th>{{ $t("等级") }}</th><th>{{ $t("个人 / 小区业绩") }}</th><th>{{ $t("总额度 / 已用") }}</th><th>{{ $t("操作") }}</th></tr></thead><tbody><tr v-for="a in accounts.data" :key="a.id"><td>#{{a.id}}</td><td>{{a.code}}<small>{{ $t("上级") }} {{a.parent_code || $t('无')}}</small></td><td>V{{a.level}}<small v-if="a.reward_excluded">{{ $t("动态奖励排除") }}</small></td><td>{{fmt(a.personal)}} / {{fmt(a.small_area)}}</td><td>{{fmt(a.quota_total)}} / {{fmt(a.quota_used)}}</td><td><Link :href="route('admin.umi.business',{...accountFilters,search:accountSearch,accounts_page:accounts.current_page,account:a.id})">{{ $t("查看 / 管理") }}</Link></td></tr></tbody></table></div><nav class="ub-pages"><Link v-if="accounts.prev_page_url" :href="accounts.prev_page_url">{{ $t('Previous') }}</Link><span>{{accounts.current_page}} / {{accounts.last_page}} · {{accounts.total}}</span><Link v-if="accounts.next_page_url" :href="accounts.next_page_url">{{ $t('Next') }}</Link></nav></section>
<div v-if="portfolio" class="ub-admin-grid"><section class="ub-card"><h2>{{ $t("账户") }} {{portfolio.account.code}}</h2><dl><div v-for="(value,key) in portfolio.balances" :key="key"><dt>{{pocketName(key)}}</dt><dd>{{fmt(value)}}</dd></div></dl><h2 style="margin-top:24px">{{ $t("释放计划") }}</h2><div class="ub-table"><table><thead><tr><th>{{ $t("计划") }}</th><th>{{ $t("日比例") }}</th><th>{{ $t("已释放") }}</th><th>{{ $t("状态") }}</th></tr></thead><tbody><tr v-for="p in portfolio.plans" :key="p.id"><td>#{{p.id}}</td><td>{{percent(p.release?.daily_rate??p.daily_rate)}}</td><td>{{fmt(p.released)}}</td><td>{{statusName(p.status==='completed'?'completed':p.release?.status??p.status)}}</td></tr></tbody></table></div></section>
<section class="ub-card"><h2>{{ $t("账户业务操作") }}</h2><form @submit.prevent="manageAccount"><fieldset :disabled="busy || state.read_only" class="ub-fieldset"><label>{{ $t("业务") }}<themed-select v-model="action"><option value="gift">{{ $t("赠送额度与释放计划") }}</option><option value="quota">{{ $t("调整总额度") }}</option><option value="level">{{ $t("等级下限与动态排除") }}</option></themed-select></label><template v-if="action==='gift'||action==='quota'"><label>{{action==='gift'?$t("赠送本金 · UMI"):$t("调整额度 · UMI")}}<input v-model.trim="amount" inputmode="decimal" required /></label><label v-if="action==='gift'">{{ $t("倍数") }}<input v-model.trim="multiplier" inputmode="decimal" required /></label><label v-else>{{ $t("方向") }}<themed-select v-model="direction"><option value="add">{{ $t("增加") }}</option><option value="subtract">{{ $t("扣减") }}</option></themed-select></label></template><template v-if="action==='plan'"><label>{{ $t("计划") }}<themed-select v-model="planId" required><option disabled value="">{{ $t("请选择") }}</option><option v-for="p in portfolio.plans" :key="p.id" :value="p.id">#{{p.id}} · {{statusName(p.status==='completed'?'completed':p.release?.status??p.status)}}</option></themed-select></label><label>{{ $t("调整后状态") }}<themed-select v-model="planStatus"><option value="paused">{{ $t("暂停") }}</option><option value="active">{{ $t("恢复释放") }}</option></themed-select></label></template><template v-if="action==='level'"><label>{{ $t("手动等级下限") }}<themed-select v-model.number="manualLevel"><option v-for="n in 10" :key="n" :value="n-1">{{n===1?$t("自动等级"):'V'+(n-1)}}</option></themed-select></label><label>{{ $t("动态奖励") }}<themed-select v-model="excluded"><option :value="false">{{ $t("正常发放") }}</option><option :value="true">{{ $t("排除直推、团队和平级奖励") }}</option></themed-select></label></template><label>{{ $t("操作依据") }}<textarea v-model.trim="reason" required minlength="10" maxlength="2000" rows="3" /></label><p>{{ $t("调整会保留操作记录。不能改变账户上级，不能将额度扣到已使用量以下，也不能重启已完成的计划。") }}</p><button :disabled="busy">{{ $t("保存操作") }}</button></fieldset></form></section></div>
<release-manager v-if="portfolio" :portfolio="portfolio" :state="state" :key="portfolio.account.id"/><reward-details v-if="portfolio" :portfolio="portfolio"/></template>
<template v-if="tab==='settlement'"><div class="ub-admin-grid"><section class="ub-card"><h2>{{ $t("日结与业务日期") }}</h2><p>{{ $t("下一次按") }} {{state.next_date}} {{ $t("处理线性释放、团队级差、宝利息、平级、自动存入和到期解押。每个日期只允许成功执行一次，失败整批回滚。") }}</p><p>{{ $t("按业务日顺序结算，已接续的原用户从截止日之后计算。此操作记入站内账本。") }}</p><p>{{ $t("任务最近心跳：") }}{{heartbeat?new Date(heartbeat*1000).toLocaleString():$t("尚无成功心跳")}}</p><button :disabled="busy||state.paused||state.read_only" @click="previewSettlement">{{ $t("预览下一日结算") }}</button><div v-if="settlementPreview"><p>{{ $t("预计到账") }} {{fmt(settlementPreview.total)}} UMI · {{settlementPreview.rewards.length}} {{ $t("条收益 ·") }} {{settlementPreview.pending.length}} {{ $t("条待核对；尚未入账。") }}</p></div><button :disabled="busy||state.paused||state.read_only" @click="submit({action:'settle',day:state.next_date})">{{ $t("结算并推进到") }} {{state.next_date}}</button></section><section class="ub-card"><h2>{{state.paused?$t("恢复业务"):$t("暂停业务")}}</h2><form @submit.prevent="submit({action:'pause',paused:!state.paused,reason:pauseReason})"><fieldset :disabled="busy || state.read_only" class="ub-fieldset"><label>{{ $t("操作依据") }}<textarea v-model.trim="pauseReason" minlength="10" required rows="3"/></label><button :disabled="busy">{{state.paused?$t("恢复业务"):$t("暂停新增业务和日结")}}</button></fieldset></form></section></div><section class="ub-card"><h2>{{ $t("日结记录") }}</h2><div class="ub-table"><table><thead><tr><th>{{ $t("日期") }}</th><th>{{ $t("规则") }}</th><th>{{ $t("线性") }}</th><th>{{ $t("团队") }}</th><th>{{ $t("宝利息") }}</th><th>{{ $t("平级") }}</th><th>{{ $t("账本") }}</th></tr></thead><tbody><tr v-for="d in days" :key="d.day"><td>{{d.day}}</td><td>#{{d.rule_id}}</td><td>{{fmt(d.summary.rewards.linear)}}</td><td>{{fmt(d.summary.rewards.team)}}</td><td>{{fmt(d.summary.rewards.interest)}}</td><td>{{fmt(d.summary.rewards.peer)}}</td><td>{{d.summary.ledger_ok?$t("已核平"):$t("待核查")}}</td></tr></tbody></table></div></section></template>
<template v-if="tab==='rules'"><section class="ub-card"><h2>{{ $t("规则配置") }}</h2><p>{{ $t("比例用小数填写：0.008 = 0.8%，0.30 = 30%。保存生成新版本；已有计划日比例、解押费率和解锁时间不受影响。日结参数从本业务日起生效，补结更早日期使用对应旧版本。") }}</p><form @submit.prevent="saveRules"><fieldset :disabled="busy || state.read_only" class="ub-fieldset"><div class="ub-rule-grid"><label v-for="f in ruleFields" :key="f.key">{{f.name}}<input v-model.trim="formRules[f.key]" inputmode="decimal" required /></label><label>{{ $t("宝提取手续费来源") }}<themed-select v-model="formRules.treasure_fee_source"><option value="proceeds">{{ $t("从提取额内扣除") }}</option><option value="reserve">{{ $t("从储备金扣除并记录内部积分") }}</option></themed-select></label><label>{{ $t("平级规则（尚无 V4+ 实际样本）") }}<themed-select v-model="formRules.peer_policy"><option value="nearest_equal_nonrecursive">{{ $t("已确认新版本：最近同级、不递归") }}</option><option value="disabled">{{ $t("停用平级奖励") }}</option></themed-select></label></div><rule-tables :value="formRules"/><label>{{ $t("配置变更依据") }}<textarea v-model.trim="ruleReason" minlength="10" required rows="3" /></label><button :disabled="busy">{{ $t("保存新的规则版本") }}</button></fieldset></form></section><section class="ub-card"><h2>{{ $t("等级门槛与级差（V1–V3 有历史样本）") }}</h2><div class="ub-table"><table><thead><tr><th>{{ $t("等级") }}</th><th>{{ $t("个人门槛 USDT") }}</th><th>{{ $t("小区业绩 USDT") }}</th><th>{{ $t("级差比例") }}</th></tr></thead><tbody><tr v-for="r in state.rules.ranks" :key="r.level"><td>V{{r.level}}</td><td>{{r.personal}}</td><td>{{r.small}}</td><td>{{percent(r.rate)}}</td></tr></tbody></table></div></section><section class="ub-card"><h2>{{ $t("版本记录") }}</h2><details v-for="v in versions" :key="v.id" class="ub-card"><summary>#{{v.id}} · {{v.created_at}} · {{v.reason}}</summary><pre class="ub-json">{{JSON.stringify(v.rules,null,2)}}</pre><small>SHA-256 {{v.digest}}</small></details></section></template>
<template v-if="tab==='corrections'"><section class="ub-card"><h2>{{ $t("待核对收益与补发") }}</h2><p>{{ $t("这里只处理系统已记录、尚未到账的收益。补发须填写核对依据，重复处理将被拒绝；补发仍占用剩余额度和收益池。") }}</p><div class="ub-table"><table><thead><tr><th>{{ $t("选择") }}</th><th>{{ $t("日期 / 账户") }}</th><th>{{ $t("类型") }}</th><th>{{ $t("应得 UMI") }}</th><th>{{ $t("原因") }}</th></tr></thead><tbody><tr v-for="p in pendingRewards" :key="p.id"><td><input type="checkbox" :value="p.id" v-model="correctionIds" /></td><td>{{p.business_date}} / #{{p.account_id}}</td><td>{{p.kind}}</td><td>{{fmt(p.amount)}}</td><td>{{ $t(p.reason) }}</td></tr></tbody></table></div><p v-if="!pendingRewards.length">{{ $t("当前没有待补发记录。") }}</p><form @submit.prevent="submit({action:'reward_correction',ids:correctionIds,reason:correctionReason})"><fieldset :disabled="busy||state.read_only" class="ub-fieldset"><label>{{ $t("核对依据") }}<textarea v-model.trim="correctionReason" minlength="10" required /></label><button :disabled="!correctionIds.length">{{ $t("补发所选记录") }}</button></fieldset></form></section></template>
<template v-if="tab==='audit'"><section class="ub-card"><h2>{{ $t("账务核查") }}</h2><p>{{ $t("核对每笔操作按币种借贷平衡、逐笔余额链、余额表及已发收益与已用额度，当前") }} {{audit.entries}} {{ $t("条分录。") }}</p><p :class="audit.ok?'ub-ok':'ub-bad'">{{audit.ok?$t("核查通过"):$t("核查失败：")+audit.errors.join('；')}}</p><a :href="route('admin.umi.business.shadow')">{{ $t("原机制逐户影子核验 →") }}</a> · <a :href="route('admin.umi.reconciliation')">{{ $t("核对原用户档案 →") }}</a></section><section class="ub-card"><h2>{{ $t("最近 30 次操作") }}</h2><details v-for="o in operations" :key="o.id" class="ub-card"><summary>{{o.created_at}} · {{operationName(o.type)}} · #{{o.account_id || $t("全局")}}</summary><small>{{ $t("操作号") }} {{o.id}} {{ $t("· 规则 #") }}{{o.rule_id}} {{ $t("· 操作人 #") }}{{o.actor_id}}</small><pre class="ub-json">{{pretty(o.details)}}</pre></details></section></template>
<details class="ub-card ub-assumptions"><summary>{{ $t("依据、补全假设与边界") }}</summary><p v-for="(a,i) in state.rules.assumptions" :key="i">{{ $t(a) }}</p><p>{{ $t("本轮未恢复原服务器的完整日结日志与全部有效计划，原档案不会被候选计算覆盖。") }}</p></details>
</main></admin-layout></template>
<script>
import { legacyText } from '@/Functions/LegacyTranslation';

import AdminLayout from '@/Layouts/AdminLayout';import ReleaseManager from './ReleaseManager.vue';import RuleTables from './RuleTables.vue';import RewardDetails from './RewardDetails.vue';import axios from 'axios';import '../../Umi/business.scss';
export default{components:{AdminLayout,ReleaseManager,RuleTables,RewardDetails},props:{heartbeat:{default:null},pendingRewards:{type:Array,default:()=>[]},pools:{type:Array,default:()=>[]},settlementError:{type:String,default:null},state:Object,accounts:Object,accountTotal:Number,accountSearch:String,accountFilters:Object,portfolio:Object,audit:Object,days:Array,versions:Array,operations:Array},
data(){return{search:this.accountSearch||'',accountForm:{level:'',binding:'',rewards:'',...this.accountFilters},settlementPreview:null,correctionIds:[],correctionReason:'',poolTarget:'distribution',poolAsset:'UMI',poolAmount:'',tab:'accounts',busy:false,error:'',message:'',pending:null,noticeTimer:null,action:'gift',amount:'',multiplier:'3',direction:'add',planId:'',planStatus:'paused',manualLevel:this.portfolio?.account.manual_level||0,excluded:this.portfolio?.account.reward_excluded||false,reason:'',pauseReason:'',ruleReason:'',formRules:JSON.parse(JSON.stringify(this.state.rules)),tabs:[{id:'accounts',name:legacyText("账户与计划")},{id:'settlement',name:legacyText("每日结算")},{id:'corrections',name:legacyText("收益补发")},{id:'rules',name:legacyText("规则版本")},{id:'audit',name:legacyText("账务与审计")}],ruleFields:[{key:'price',name:legacyText("UMI 参考价 · USDT")},{key:'purchase_daily_rate',name:legacyText("新认购日释放比例")},{key:'gift_daily_rate',name:legacyText("新赠送日释放比例")},{key:'referral_rate',name:legacyText("直推奖励比例")},{key:'treasure_daily_rate',name:legacyText("UMI 宝日计息比例")},{key:'treasure_fee',name:legacyText("UMI 宝提取手续费")},{key:'linear_fee',name:legacyText("线性收益划转费")},{key:'team_fee',name:legacyText("团队收益划转费")},{key:'referral_fee',name:legacyText("直推收益划转费")},{key:'swap_fee',name:legacyText("兑换手续费")},{key:'transfer_fee',name:legacyText("站内转账手续费")},{key:'unstake_minutes',name:legacyText("新解押等待时间 · 分钟")},{key:'vip_fee',name:legacyText("新解押手续费")},{key:'peer_rate',name:legacyText("平级候选奖励比例")},{key:'peer_min_level',name:legacyText("平级起始等级（1–9）")}]};},
methods:{async previewSettlement(){this.error='';this.busy=true;try{const {data}=await axios.post(this.route('admin.umi.business.preview'),{day:this.state.next_date});this.settlementPreview=data;}catch(e){this.error=Object.values(e.response?.data?.errors||{}).flat().join('；')||legacyText("预览失败，请核对结算日期和资金池。");}finally{this.busy=false;}},fmt(n){return String(n==null?'0':n).replace(/(\.\d*?)0+$/,'$1').replace(/\.$/,'');},percent(n){return (Number(n)*100).toLocaleString('zh-CN',{maximumFractionDigits:8})+'%';},statusName(s){return {active:legacyText("释放中"),paused:legacyText("已暂停"),completed:legacyText("已完成")}[s]||s;},pocketName(s){return {main:legacyText("可用 UMI"),usdt:legacyText("可用 USDT"),linear:legacyText("线性收益"),team:legacyText("团队收益"),referral:legacyText("直推收益"),treasure:legacyText("UMI 宝"),reserve:legacyText("储备金"),vip:legacyText("VIP 质押"),unstaking:legacyText("解押中"),points:legacyText("内部积分")}[s]||s;},pretty(s){try{return JSON.stringify(JSON.parse(s),null,2);}catch(_){return s;}},operationName(s){return {enroll:legacyText("开通账户"),purchase:legacyText("认购"),gift:legacyText("赠送"),settle:legacyText("日结"),pause:legacyText("业务启停"),plan:legacyText("计划状态"),level:legacyText("等级与排除"),quota:legacyText("额度调整"),custody_transfer:legacyText("实充资金划转"),fixture_funding:legacyText("验收资金"),claim:legacyText("收益划转"),treasure_deposit:legacyText("宝存入"),treasure_withdraw:legacyText("宝提取"),reserve_deposit:legacyText("储备存入"),swap:legacyText("兑换"),transfer:legacyText("站内转账"),stake:legacyText("质押"),unstake:legacyText("解押"),release_revision:legacyText("释放调整"),continuity:legacyText("历史期初接续"),reward_correction:legacyText("核对后补发"),claim_to_wallet:legacyText("领取至资金账户")}[s]||s;},
